llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "2-Methoxyestradiol, an estradiol analogue sharing the phenolic A-ring and steroid core, has clinical oral bioavailability of only 1–2%, demonstrating that estradiol-like steroids undergo extensive first-pass metabolism and poor systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Progesterone, a steroid hormone, has ingested oral bioavailability less than 10% due to gut and hepatic metabolism, supporting low oral bioavailability for unmodified steroid scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine, the highest-transfer analogue, has a mean oral bioavailability of 18% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Danazol, a lipophilic steroid, has absolute oral bioavailability of 11±5.2% in the fasted state, showing that lipophilic steroids can still have low systemic F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Estramustine phosphate, an estradiol derivative, showed no detectable parent drug in plasma after oral administration, indicating very low oral bioavailability for estradiol-based prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Nomegestrol acetate, a structurally modified steroid ester/progestin, achieved ~63% absolute oral bioavailability, providing a contradictory example that some steroid esters can be well absorbed orally.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, especially from estradiol-like and steroid analogues, indicates low oral bioavailability (<20%) for the query estradiol cypionate; the ester prodrug is unlikely to overcome extensive first-pass metabolism of the released estradiol. Occasional high values in fed-state or structurally modified steroids do not outweigh the consistent low F measurements.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate itself.",
    "Formulation and fed-state dependence of the query are unknown.",
    "Contradictory records for estramustine phosphate and nomegestrol acetate create uncertainty about steroid ester absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

